tape( 'the function is a constructor which does not require the `new` operator', function test( t ) {
	var results;
	var res;

	results = Float32Results;

	res = results();
	t.strictEqual( res instanceof results, true, 'returns expected value' );

	res = results( {} );
	t.strictEqual( res instanceof results, true, 'returns expected value' );

	res = results( new ArrayBuffer( 1024 ) );
	t.strictEqual( res instanceof results, true, 'returns expected value' );

	res = results( new ArrayBuffer( 1024 ), 0 );
	t.strictEqual( res instanceof results, true, 'returns expected value' );

	res = results( new ArrayBuffer( 1024 ), 0, 1024 );
	t.strictEqual( res instanceof results, true, 'returns expected value' );

	t.end();
});

tape( 'the function is a constructor for a fixed-width results object ', function test( t ) {
	var expected;
	var actual;

	actual = new Float32Results({
		'replicates': 4,
		'replicate': 2,
		'metric': 'sqeuclidean',
		'iterations': 10,
		'algorithm': 'lloyd',
		'inertia': f32( 3.28 ),
		'k': 4,
		'samples': 10,
		'features': 3
	});

	expected = {
		'replicates': 4,
		'replicate': 2,
		'metric': 'sqeuclidean',
		'iterations': 10,
		'algorithm': 'lloyd',
		'inertia': f32( 3.28 ),
		'k': 4,
		'samples': 10,
		'features': 3
	};

	t.strictEqual( Number( actual.replicates ), expected.replicates, 'returns expected value' );
	t.strictEqual( Number( actual.replicate ), expected.replicate, 'returns expected value' );
	t.strictEqual( actual.metric, expected.metric, 'returns expected value' );
	t.strictEqual( Number( actual.iterations ), expected.iterations, 'returns expected value' );
	t.strictEqual( actual.algorithm, expected.algorithm, 'returns expected value' );
	t.strictEqual( actual.inertia, expected.inertia, 'returns expected value' );
	t.strictEqual( Number( actual.k ), expected.k, 'returns expected value' );
	t.strictEqual( Number( actual.samples ), expected.samples, 'returns expected value' );
	t.strictEqual( Number( actual.features ), expected.features, 'returns expected value' );
	t.end();
});

