tape( 'the function is a constructor for a fixed-width results object (ArrayBuffer)', function test( t ) {
	var expected;
	var actual;
	var buf;

	buf = new ArrayBuffer( 1024 );
	actual = new Float32Results( buf );

	actual.replicates = 4;
	actual.replicate = 2;
	actual.metric = 'sqeuclidean';
	actual.iterations = 10;
	actual.algorithm = 'lloyd';
	actual.inertia = f32( 3.28 );
	actual.k = 4;
	actual.samples = 10;
	actual.features = 3;

	expected = {
		'replicates': 4,
		'replicate': 2,
		'metric': 'sqeuclidean',
		'iterations': 10,
		'algorithm': 'lloyd',
		'inertia': f32( 3.28 ),
		'k': 4,
		'samples': 10,
		'features': 3
	};

	t.strictEqual( actual instanceof Float32Results, true, 'returns expected value' );
	t.strictEqual( actual.toDataView().buffer, buf, 'returns expected value' );
	t.strictEqual( actual.toDataView().byteOffset, 0, 'returns expected value' );
	t.strictEqual( Number( actual.replicates ), expected.replicates, 'returns expected value' );
	t.strictEqual( Number( actual.replicate ), expected.replicate, 'returns expected value' );
	t.strictEqual( actual.metric, expected.metric, 'returns expected value' );
	t.strictEqual( Number( actual.iterations ), expected.iterations, 'returns expected value' );
	t.strictEqual( actual.algorithm, expected.algorithm, 'returns expected value' );
	t.strictEqual( actual.inertia, expected.inertia, 'returns expected value' );
	t.strictEqual( Number( actual.k ), expected.k, 'returns expected value' );
	t.strictEqual( Number( actual.samples ), expected.samples, 'returns expected value' );
	t.strictEqual( Number( actual.features ), expected.features, 'returns expected value' );
	t.end();
});

